// Fetches the pictures for Hot things' examples and writes:
//   assets/examples/<key>.webp   a 320 x 200 crop, the tile picture
//   data/examples.js             title, author, licence and source of each, for the app (do not edit by hand)
//   docs/credits-examples.md     the same, for people
// Pictures come from Wikimedia Commons, with author and licence read from the Commons API (never typed in
// here); a licence that forbids commercial use or changes is refused. The Sun reuses the sky view's picture
// and its credit from data/sky.js.
//
// Run: node tools/fetch_examples.mjs            fetch anything missing, then rebuild the credits
//      node tools/fetch_examples.mjs lava sun   fetch these again
import { writeFile, mkdir, readFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { join } from 'node:path';
import sharp from 'sharp';
import { PRESETS } from '../js/blackbody.js';
import { SKY } from '../data/sky.js';

const ROOT = new URL('..', import.meta.url).pathname;
const OUT = join(ROOT, 'assets/examples');
const UA = { 'User-Agent': 'FullSpectrum/0.1 (https://spectrum.moleculeviewer.org; tools/fetch_examples.mjs)' };

// One picture for each preset in js/blackbody.js: a Commons file, or a picture already in the repo. `focus`:
// where to keep when cropping (sharp's position names).
const SOURCES = {
  cmb: { commons: 'Cosmic Microwave Background (CMB).jpeg', note: 'the Planck map of the whole sky' },
  nitrogen: { commons: 'Liquidnitrogen.jpg' },
  you: { commons: 'Human-Infrared.jpg', focus: 'west', note: 'in infrared' },
  oven: { commons: 'Opened oven seen with thermal camera.jpg', note: 'in infrared' },
  'red-hot': { commons: 'Red hot iron is forged with hammer and anvil.jpg' },
  lava: { commons: 'Pāhoehoe Lava flow.JPG' },
  filament: { commons: 'Incandescent Lamp Filament.jpg' },
  sun: { sky: 'assets/sky/sun-visible.jpg' },
  sirius: { commons: 'Sirius A and B Hubble photo.jpg', note: 'with its white dwarf companion at lower left' },
  spica: { commons: 'Spica DSS.png' },
  corona: { commons: '2024 Total Solar Eclipse Corona.jpg', note: 'in a total eclipse' },
};

const strip = html => (html ?? '').replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#039;/g, "'").replace(/\s+/g, ' ').trim();

async function commons(title) {
  const url = `https://commons.wikimedia.org/w/api.php?${new URLSearchParams({ action: 'query', titles: `File:${title}`, prop: 'imageinfo', iiprop: 'url|extmetadata', iiurlwidth: 1200, format: 'json' })}`;
  const page = Object.values((await (await fetch(url, { headers: UA })).json()).query.pages)[0];
  const ii = page.imageinfo?.[0], m = ii?.extmetadata ?? {};
  if (!ii) throw new Error(`${title}: not on Commons`);
  const licence = strip(m.LicenseShortName?.value);
  if (/NC|ND/.test(licence)) throw new Error(`${title}: licence ${licence} is not one we can use`);
  const img = new Uint8Array(await (await fetch(ii.thumburl, { headers: UA })).arrayBuffer());
  return { img, meta: { title: title.replace(/\.\w+$/, ''), author: strip(m.Artist?.value) || strip(m.Credit?.value), licence, licenceUrl: m.LicenseUrl?.value ?? null, source: ii.descriptionurl, site: 'Wikimedia Commons' } };
}

function fromSky(file) {
  const im = SKY.flatMap(o => o.images).find(i => i.file === file);
  return { meta: { title: im.label, author: im.credit, licence: im.licence, licenceUrl: null, source: im.url, site: 'the sky view' }, path: join(ROOT, file) };
}

await mkdir(OUT, { recursive: true });
const wanted = process.argv.slice(2);
for (const p of PRESETS) {
  const s = SOURCES[p.key];
  if (!s) { console.log(`FAIL  ${p.key}: no picture`); process.exitCode = 1; continue; }
  const file = join(OUT, `${p.key}.webp`);
  if (wanted.length ? !wanted.includes(p.key) : existsSync(file)) continue;
  try {
    const got = s.commons ? await commons(s.commons) : fromSky(s.sky);
    await sharp(got.img ?? got.path).resize(320, 200, { fit: 'cover', position: s.focus ?? 'centre' }).webp({ quality: 80 }).toFile(file);
    const meta = { key: p.key, ...got.meta, note: s.note ?? null, changes: 'cropped to 320 x 200 and saved as WebP', fetched: new Date().toISOString().slice(0, 10) };
    await writeFile(join(OUT, `${p.key}.json`), JSON.stringify(meta, null, 2) + '\n');
    console.log(`ok    ${p.key}: ${meta.title} by ${meta.author}, ${meta.licence}`);
  } catch (err) { console.log(`FAIL  ${p.key}: ${err.message}`); process.exitCode = 1; }
}

// The credits, rebuilt from every picture on disk, in the presets' order.
const metas = [];
for (const p of PRESETS) if (existsSync(join(OUT, `${p.key}.json`))) metas.push(JSON.parse(await readFile(join(OUT, `${p.key}.json`), 'utf8')));
await writeFile(join(ROOT, 'data/examples.js'), `// Generated by tools/fetch_examples.mjs from assets/examples/*.json; do not edit by hand.
// The pictures on Hot things' example tiles, with their credits. Full notes: docs/credits-examples.md.
export const EXAMPLE_PICTURES = {
${metas.map(m => `  ${JSON.stringify(m.key)}: ${JSON.stringify({ file: `assets/examples/${m.key}.webp`, title: m.title, author: m.author, licence: m.licence, licenceUrl: m.licenceUrl, source: m.source, note: m.note })},`).join('\n')}
};
`);
await writeFile(join(ROOT, 'docs/credits-examples.md'), `# Credits: pictures of Hot things' examples

Generated by \`tools/fetch_examples.mjs\`, which reads each picture's author and licence from Wikimedia Commons
and refuses licences that forbid commercial use or changes. Each is cropped to 320 x 200 and saved as WebP in
\`assets/examples/\`; pictures under CC BY-SA are shared under the same licence. The app names each picture's
author and licence in the Hot things panel.

${metas.map(m => `- **${m.key}**: [${m.title}](${m.source})${m.note ? ` (${m.note})` : ''} by ${m.author}, from ${m.site}. Licence: ${m.licenceUrl ? `[${m.licence}](${m.licenceUrl})` : m.licence}. Changes: ${m.changes}. Fetched ${m.fetched}.`).join('\n')}
`);
console.log(`credits: ${metas.length} pictures`);
